diff --git a/.github/workflows/build-macos.yml b/.github/workflows/build-macos.yml
index a99c9b4400..33978a7585 100644
--- a/.github/workflows/build-macos.yml
+++ b/.github/workflows/build-macos.yml
@@ -654,7 +654,15 @@ jobs:
           # run_attempt*2 + archIndex stays monotonic: the next dispatch
           # (+10) always exceeds every attempt/arch combo of the previous
           # run, so a re-upload is always legal.
-          BUILD_NUMBER: ${{ github.run_number * 10 + github.run_attempt * 2 + (matrix.arch == 'arm64' && 1 || 0) }}
+          # gh-2288: GitHub expression syntax has NO additive '+' — the
+          # inline sum made the whole file unparseable (dispatch API 422
+          # "Unexpected symbol: '+'", daily cli leg dead, run
+          # 44243345944). The raw operands travel as plain env scalars;
+          # the run block computes the sum in bash, which has additive
+          # arithmetic. Pinned by test/workflow_expression_arithmetic_
+          # guard_test.dart (AC2) + build_macos_asc_collision_guard_test.
+          RUN_NUMBER: ${{ github.run_number }}
+          RUN_ATTEMPT: ${{ github.run_attempt }}
           BUILD_VERSION: ${{ needs.version.outputs.version }}
           # gh-1865: CODE_SIGN_IDENTITY as a SHA-1 fingerprint (read from
           # THIS job's own keychain right after import) instead of the
@@ -667,7 +675,13 @@ jobs:
           PROFILE_TEAM: ${{ steps.signing.outputs.profile_team }}
         run: |
           ARCH="${{ matrix.arch }}"
-          echo "Building for architecture: $ARCH"
+          # gh-2246 BUILD_NUMBER, computed HERE because GitHub expressions
+          # have no additive '+' (gh-2288): run_number*10 + run_attempt*2
+          # + archIndex stays monotonic — the next dispatch (+10) always
+          # exceeds every attempt/arch combo of the previous run.
+          if [ "$ARCH" = "arm64" ]; then ARCH_INDEX=1; else ARCH_INDEX=0; fi
+          BUILD_NUMBER=$(( RUN_NUMBER * 10 + RUN_ATTEMPT * 2 + ARCH_INDEX ))
+          echo "Building for architecture: $ARCH (BUILD_NUMBER=$BUILD_NUMBER)"
           cd flutter_app
           if [ -n "${CERT_SHA1:-}" ]; then
             export FA_CODE_SIGN_IDENTITY="$CERT_SHA1"
diff --git a/test/build_macos_asc_collision_guard_test.dart b/test/build_macos_asc_collision_guard_test.dart
index 474a29aac4..ea001807d2 100644
--- a/test/build_macos_asc_collision_guard_test.dart
+++ b/test/build_macos_asc_collision_guard_test.dart
@@ -82,34 +82,42 @@ void main() {
         'Build macOS release (\${{ matrix.arch }})',
       );
       final env = (buildStep.value)['env'] as Map;
-      final buildNumber = env['BUILD_NUMBER'];
+      // gh-2288: GitHub expressions have no additive '+' — the gh-2246
+      // inline sum made the whole workflow unparseable (dispatch API
+      // 422 "Unexpected symbol: '+'"). The raw operands ride as env
+      // scalars; the run block performs the sum in bash. Pinned by
+      // workflow_expression_arithmetic_guard_test.dart (AC1/AC2).
       expect(
-        buildNumber,
-        isA<String>(),
-        reason: 'BUILD_NUMBER must stay an env var',
+        env.keys,
+        isNot(contains('BUILD_NUMBER')),
+        reason: 'an env BUILD_NUMBER expression is what 422s the file',
       );
-      final expr = buildNumber as String;
       expect(
-        expr,
+        env['RUN_NUMBER'],
         contains('github.run_number'),
         reason: 'monotonic growth across dispatches',
       );
       expect(
-        expr,
+        env['RUN_ATTEMPT'],
         contains('github.run_attempt'),
         reason:
             'gh-2246: reruns reuse run_number — the attempt term is what '
             'makes re-uploads legal (altool -19232 fix)',
       );
+      final run = (buildStep.value)['run'] as String? ?? '';
       expect(
-        expr,
-        contains('matrix.arch'),
-        reason: 'gh-2246: sibling arch legs must not race one ASC build',
+        run,
+        contains(
+          r'BUILD_NUMBER=$(( RUN_NUMBER * 10 + RUN_ATTEMPT * 2 + ARCH_INDEX ))',
+        ),
+        reason:
+            'the gh-2246 formula must stay intact — only its computation '
+            'site moved into bash (gh-2288)',
       );
       expect(
-        expr,
-        isNot(equals(r'${{ github.run_number }}')),
-        reason: 'the bare form IS the collision',
+        run,
+        contains(r'[ "$ARCH" = "arm64" ]'),
+        reason: 'gh-2246: sibling arch legs must not race one ASC build',
       );
     },
   );
diff --git a/test/workflow_expression_arithmetic_guard_test.dart b/test/workflow_expression_arithmetic_guard_test.dart
new file mode 100644
index 0000000000..f743d63220
--- /dev/null
+++ b/test/workflow_expression_arithmetic_guard_test.dart
@@ -0,0 +1,124 @@
+// gh-2288 — the daily-publish `cli` leg died at DISPATCH: HTTP 422
+// "failed to parse workflow: (Line: 657, Col: 25): Unexpected symbol:
+// '+'" because build-macos.yml (gh-2246) wrote an additive sum INSIDE
+// a ${{ }} expression. GitHub Actions expression syntax has no
+// additive '+'/'-' — the file itself is unparseable, so EVERY dispatch
+// of the workflow is rejected before any job starts (daily run
+// 44243345944, leg `cli`; LEG_CLI_URL stayed empty — there was no
