+  final workflowFiles =
+      Directory(workflowsDir)
+          .listSync()
+          .whereType<File>()
+          .where((f) => f.path.endsWith('.yml'))
+          .toList()
+        ..sort((a, b) => a.path.compareTo(b.path));
